from decimal import Decimal, InvalidOperation, ROUND_FLOOR, ROUND_HALF_EVEN, ROUND_HALF_UP

_MODE = {
    "setengah_atas": ROUND_HALF_UP,
    "bankir": ROUND_HALF_EVEN,
    "ke_bawah": ROUND_FLOOR,
}


def bulatkan_rupiah(nilai: str, kelipatan: int, mode: str) -> int:
    if mode not in _MODE:
        raise ValueError(f"mode tidak dikenal: {mode!r}")
    if kelipatan <= 0:
        raise ValueError("kelipatan harus positif")
    try:
        angka = Decimal(nilai)
    except InvalidOperation:
        raise ValueError(f"nilai tidak valid: {nilai!r}") from None
    if not angka.is_finite():
        raise ValueError(f"nilai tidak valid: {nilai!r}")
    hasil_bagi = (angka / kelipatan).quantize(Decimal(1), rounding=_MODE[mode])
    return int(hasil_bagi) * kelipatan

