def cari_kesalahan_kurung(kode: str) -> int:
    pasangan = {")": "(", "]": "[", "}": "{"}
    tumpukan = []
    n = len(kode)
    i = 0
    while i < n:
        ch = kode[i]
        if ch in "\"'":
            awal = i
            i += 1
            while i < n and kode[i] != ch:
                if kode[i] == "\\":
                    i += 1
                i += 1
            if i >= n:
                return awal
        elif ch in "([{":
            tumpukan.append(i)
        elif ch in ")]}":
            if not tumpukan or kode[tumpukan[-1]] != pasangan[ch]:
                return i
            tumpukan.pop()
        i += 1
    return tumpukan[-1] if tumpukan else -1

