from collections import deque


def hitung_pulau(peta: list) -> tuple:
    if not peta:
        return (0, 0)
    lebar = len(peta[0])
    for baris in peta:
        if len(baris) != lebar:
            raise ValueError("panjang baris tidak sama")
        if any(ch not in "#." for ch in baris):
            raise ValueError("karakter tidak dikenal")
    tinggi = len(peta)
    dikunjungi = set()
    jumlah, terbesar = 0, 0
    for r in range(tinggi):
        for c in range(lebar):
            if peta[r][c] != "#" or (r, c) in dikunjungi:
                continue
            jumlah += 1
            luas = 0
            antrian = deque([(r, c)])
            dikunjungi.add((r, c))
            while antrian:
                y, x = antrian.popleft()
                luas += 1
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < tinggi and 0 <= nx < lebar and peta[ny][nx] == "#" and (ny, nx) not in dikunjungi:
                        dikunjungi.add((ny, nx))
                        antrian.append((ny, nx))
            terbesar = max(terbesar, luas)
    return (jumlah, terbesar)

