from decimal import Decimal, ROUND_HALF_UP


def hitung_faktur(item: list, kode_voucher=None) -> dict:
    subtotal = 0
    for it in item:
        harga = it["harga"]
        jumlah = it["jumlah"]
        diskon_persen = it.get("diskon_persen", 0)
        if harga < 0 or jumlah < 1 or not 0 <= diskon_persen <= 100:
            raise ValueError(f"item tidak valid: {it!r}")
        kotor = harga * jumlah
        subtotal += kotor - kotor * diskon_persen // 100
    if kode_voucher is None:
        potongan = 0
    elif kode_voucher == "HEMAT10":
        potongan = min(subtotal * 10 // 100, 50_000) if subtotal >= 200_000 else 0
    elif kode_voucher == "POTONG25RB":
        potongan = 25_000 if subtotal >= 100_000 else 0
    else:
        raise ValueError(f"kode voucher tidak dikenal: {kode_voucher!r}")
    dpp = subtotal - potongan
    ppn = int((Decimal(dpp) * 11 / 100).quantize(Decimal(1), rounding=ROUND_HALF_UP))
    return {"subtotal": subtotal, "potongan": potongan, "dpp": dpp, "ppn": ppn, "total": dpp + ppn}

