import heapq


def rute_termurah(jalan: list, asal: str, tujuan: str):
    tetangga = {}
    for a, b, biaya in jalan:
        if biaya < 0:
            raise ValueError("biaya tidak boleh negatif")
        tetangga.setdefault(a, []).append((b, biaya))
        tetangga.setdefault(b, []).append((a, biaya))
    if asal == tujuan:
        return (0, [asal])
    heap = [(0, 0, [asal])]
    selesai = set()
    while heap:
        biaya, ruas, rute = heapq.heappop(heap)
        kota = rute[-1]
        if kota in selesai:
            continue
        selesai.add(kota)
        if kota == tujuan:
            return (biaya, rute)
        for berikut, w in tetangga.get(kota, []):
            if berikut not in selesai:
                heapq.heappush(heap, (biaya + w, ruas + 1, rute + [berikut]))
    return None

