def hitung_usia(lahir: datetime.date, acuan: datetime.date) -> tuple:
    if acuan < lahir:
        raise ValueError("tanggal acuan sebelum tanggal lahir")
    k = (acuan.year - lahir.year) * 12 + (acuan.month - lahir.month)
    while k > 0 and _tambah_bulan(lahir, k) > acuan:
        k -= 1
    hari = (acuan - _tambah_bulan(lahir, k)).days
    return (k // 12, k % 12, hari)

