from collections import OrderedDict


def simulasi_lru(kapasitas: int, operasi: list) -> list:
    if kapasitas < 1:
        raise ValueError("kapasitas minimal 1")
    cache = OrderedDict()
    hasil = []
    for op in operasi:
        if op[0] == "put":
            _, kunci, nilai = op
            if kunci in cache:
                cache.move_to_end(kunci)
            cache[kunci] = nilai
            if len(cache) > kapasitas:
                cache.popitem(last=False)
        elif op[0] == "get":
            kunci = op[1]
            if kunci in cache:
                cache.move_to_end(kunci)
                hasil.append(cache[kunci])
            else:
                hasil.append(None)
        else:
            raise ValueError(f"operasi tidak dikenal: {op[0]!r}")
    return hasil

