def parse_ini(teks: str) -> dict:
    hasil = {}
    bagian = ""
    for baris in teks.splitlines():
        b = baris.strip()
        if not b or b[0] in ";#":
            continue
        if b.startswith("[") and b.endswith("]"):
            bagian = b[1:-1].strip()
            hasil.setdefault(bagian, {})
            continue
        if "=" not in b:
            raise ValueError(f"baris tidak valid: {baris!r}")
        kunci, nilai = b.split("=", 1)
        kunci = kunci.strip().lower()
        if not kunci:
            raise ValueError(f"kunci kosong: {baris!r}")
        hasil.setdefault(bagian, {})[kunci] = nilai.strip()
    return hasil

