def ongkos_kirim(berat_gram: int, tarif_per_kg: int) -> int:
    if berat_gram <= 0 or tarif_per_kg < 0:
        raise ValueError("berat harus positif dan tarif tidak negatif")
    kg, lebih = divmod(berat_gram, 1000)
    if lebih > 300:
