_DIGIT = "0123456789"
_HURUF = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"


def dekode(s: str) -> str:
    tumpukan = []
    sekarang = []
    i = 0
    n = len(s)
    while i < n:
        ch = s[i]
        if ch in _DIGIT:
            j = i
            while j < n and s[j] in _DIGIT:
                j += 1
            if j >= n or s[j] != "[":
                raise ValueError("angka harus diikuti '['")
            tumpukan.append((sekarang, int(s[i:j])))
            sekarang = []
            i = j + 1
        elif ch == "]":
            if not tumpukan:
                raise ValueError("']' tanpa pasangan")
            sebelumnya, k = tumpukan.pop()
            sebelumnya.append("".join(sekarang) * k)
            sekarang = sebelumnya
            i += 1
        elif ch in _HURUF:
            sekarang.append(ch)
            i += 1
        else:
            raise ValueError(f"karakter tidak valid: {ch!r}")
    if tumpukan:
        raise ValueError("'[' tanpa pasangan")
    return "".join(sekarang)

