_GABUNGAN = ("ng", "ny", "kh", "sy")
_VOKAL = ("a", "i", "u", "e", "o")


def _token(kata: str) -> list:
    token = []
    i = 0
    while i < len(kata):
        if kata[i:i + 2] in _GABUNGAN:
