def penggal_suku_kata(kata: str) -> str:
    if not kata or any(c not in "abcdefghijklmnopqrstuvwxyz" for c in kata):
        raise ValueError("kata harus huruf kecil a-z")
    token = _token(kata)
    posisi_vokal = [i for i, t in enumerate(token) if t in _VOKAL]
    if not posisi_vokal:
        raise ValueError("kata harus mengandung vokal")
    suku = []
    awal = 0
    for a, b in zip(posisi_vokal, posisi_vokal[1:]):
        konsonan = b - a - 1
        if konsonan == 0:
            batas = b
        elif konsonan == 1:
            batas = a + 1
        else:
            batas = a + 2
        suku.append("".join(token[awal:batas]))
        awal = batas
    suku.append("".join(token[awal:]))
    return "-".join(suku)

