def histogram_teks(data: dict, lebar: int) -> list:
    if lebar < 1:
        raise ValueError("lebar minimal 1")
    if any(v < 0 for v in data.values()):
        raise ValueError("nilai tidak boleh negatif")
    if not data:
        return []
    maks = max(data.values())
    lebar_label = max(len(k) for k in data)
    baris = []
    for label, nilai in sorted(data.items(), key=lambda kv: (-kv[1], kv[0])):
        panjang = 0 if maks == 0 else (2 * nilai * lebar + maks) // (2 * maks)
        baris.append(f"{label.ljust(lebar_label)} | {'#' * panjang} {nilai}")
    return baris

