        for j in range(pos + 1, n):
            if panjang[j] == butuh and (not hasil or data[j] > hasil[-1]):
                if pilih is None or data[j] < data[pilih]:
                    pilih = j
        hasil.append(data[pilih])
        pos = pilih
        butuh -= 1
    return hasil

