def cocok_pola(pola: str, teks: str) -> bool:
    token = []
    i = 0
    while i < len(pola):
        c = pola[i]
        if c == "\\":
            if i + 1 >= len(pola):
                raise ValueError("backslash di akhir pola")
            token.append(("harfiah", pola[i + 1]))
            i += 2
        elif c == "?":
            token.append(("satu", None))
            i += 1
        elif c == "*":
            token.append(("bintang", None))
            i += 1
        else:
            token.append(("harfiah", c))
            i += 1
    n = len(teks)
    cocok = [False] * (n + 1)
    cocok[0] = True
    for jenis, ch in token:
        baru = [False] * (n + 1)
        if jenis == "bintang":
            ada = False
            for j in range(n + 1):
                ada = ada or cocok[j]
                baru[j] = ada
        else:
            for j in range(1, n + 1):
                if cocok[j - 1] and (jenis == "satu" or teks[j - 1] == ch):
                    baru[j] = True
        cocok = baru
    return cocok[n]

