import math
from fractions import Fraction


def bagi_tagihan(pesanan: dict, service_persen: int, ppn_persen: int) -> dict:
    if service_persen < 0 or ppn_persen < 0:
        raise ValueError("persen tidak boleh negatif")
    per_orang = {}
    for nama, harga in pesanan.items():
        if any(h < 0 for h in harga):
            raise ValueError("harga tidak boleh negatif")
        per_orang[nama] = sum(harga)
    subtotal = sum(per_orang.values())
    if subtotal == 0:
        return {nama: 0 for nama in pesanan}
    service = Fraction(subtotal * service_persen, 100)
    ppn = (subtotal + service) * Fraction(ppn_persen, 100)
    total = math.floor(subtotal + service + ppn + Fraction(1, 2))
    bagian = {}
    pecahan = {}
    for nama, s in per_orang.items():
        tepat = Fraction(total * s, subtotal)
        bagian[nama] = math.floor(tepat)
        pecahan[nama] = tepat - bagian[nama]
    sisa = total - sum(bagian.values())
    for nama in sorted(per_orang, key=lambda n: (-pecahan[n], n))[:sisa]:
        bagian[nama] += 1
    return bagian

