import bisect


def _bentrok(a, b):
    return a[1] <= b[2] and b[1] <= a[2]


def _terbaik(item):
    item = sorted(item, key=lambda t: t[2])
    akhir = [t[2] for t in item]
    dp = [(0, 0)]
    for i, (_, mulai, _, bayar) in enumerate(item):
        p = bisect.bisect_left(akhir, mulai, 0, i)
        ambil = (dp[p][0] + bayar, dp[p][1] - 1)
        dp.append(max(dp[i], ambil))
    return dp[-1]


def pilih_proyek(proyek: list) -> tuple:
    for nama, mulai, selesai, bayar in proyek:
        if mulai > selesai or bayar < 0:
            raise ValueError(f"proyek tidak valid: {nama!r}")
    target = _terbaik(proyek)
    jumlah = -target[1]
    dipilih = []
    for _ in range(jumlah):
        for kandidat in sorted(proyek):
            nama = kandidat[0]
            if dipilih and nama <= dipilih[-1][0]:
                continue
            if any(_bentrok(kandidat, d) for d in dipilih):
                continue
            paksa = dipilih + [kandidat]
            sisa = [t for t in proyek if t[0] > nama and not any(_bentrok(t, d) for d in paksa)]
            tambah, neg = _terbaik(sisa)
            if (sum(d[3] for d in paksa) + tambah, neg - len(paksa)) == target:
                dipilih.append(kandidat)
                break
    return (target[0], [d[0] for d in dipilih])

