import datetime

_SHIFT = ["pagi", "siang", "malam", "libur"]


def jadwal_shift(regu: list, mulai: datetime.date, tanggal: datetime.date, lama: int) -> dict:
    if len(regu) != 4:
        raise ValueError("harus ada tepat 4 regu")
    if lama < 1:
        raise ValueError("lama minimal 1 hari")
    langkah = (tanggal - mulai).days // lama
    return {nama: _SHIFT[(i + langkah) % 4] for i, nama in enumerate(regu)}

