def peringkat_kelas(nilai: dict) -> list:
    total = sorted(((sum(v), nama) for nama, v in nilai.items()), key=lambda t: (-t[0], t[1]))
    hasil = []
    for i, (jumlah, nama) in enumerate(total):
        if i > 0 and jumlah == total[i - 1][0]:
            peringkat = hasil[-1][0]
        else:
            peringkat = i + 1
        hasil.append((peringkat, nama, jumlah))
    return hasil

